0.sparql_query:
PREFIX schema: <http://schema.org/>
SELECT ?count WHERE {
  ?org a schema:Organization ;
       schema:name ?name ;
       schema:numberOfEmployees ?count .
  FILTER(CONTAINS(LCASE(?name), "steel"))
}
LIMIT 1

